insert into public.ai_knowledge (kind, area, country_code, topic, title, summary, source_name, source_url, license, lang, status) values
('management','impuestos','PE',$k$regimenes_tributarios_mype_nrus_rer_rmt_rg$k$,$k$Perú: regímenes tributarios para micro y pequeñas empresas (NRUS, RER, RMT, Régimen General)$k$,
$k$Orientación general (confirmar con contador). SUNAT ofrece cuatro regímenes: Nuevo RUS (NRUS), Régimen Especial de Renta (RER), Régimen MYPE Tributario (RMT) y Régimen General. Límites de referencia publicados por gob.pe/SUNAT: NRUS hasta S/ 96,000 anuales; RER hasta S/ 525,000 anuales de ingresos y de compras, con hasta 10 trabajadores por turno (según la tabla oficial); RMT hasta 1,700 UIT de ingresos netos anuales; Régimen General sin límite. El RMT se inscribe con RUC activo y Clave SOL, y quien supera el límite pasa al Régimen General (fuente profesional). Tasas del RMT (10% sobre las primeras 15 UIT y 29.5% el exceso) provienen de una fuente profesional: confirmar en SUNAT. Los montos y el valor de la UIT cambian: verificar el vigente. Dónde confirmar: gob.pe/280 y emprender.sunat.gob.pe.$k$,
$k$SUNAT / gob.pe$k$,$k$https://www.gob.pe/280-superintendencia-nacional-de-aduanas-y-de-administracion-tributaria-regimenes-tributarios$k$,
$k$Material informativo de portales oficiales peruanos, con apoyo de fuentes profesionales para las tasas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','CO',$k$beneficios_pequenas_empresas_progresividad_simple$k$,$k$Colombia: beneficios para pequeñas empresas (progresividad de renta y Régimen SIMPLE)$k$,
$k$Orientación general (confirmar con contador). La Ley 1429 de 2010 (reglamentada por el Decreto 4910 de 2011) creó la progresividad en el impuesto de renta para nuevas pequeñas empresas, con una tarifa que sube por años (según una fuente profesional, 0% los dos primeros años y luego aumento escalonado), solo sobre rentas de actividad mercantil y con requisitos formales, entre ellos manifestar a la DIAN la intención de acogerse. La vigencia actual de este beneficio debe confirmarse, porque reformas posteriores modificaron el sistema. La Ley 2010 de 2019 incorporó el Régimen Simple de Tributación (SIMPLE), un impuesto unificado; sus contribuyentes no son responsables de IVA cuando desarrollan solo ciertas actividades del Estatuto Tributario (art. 908). Topes, tarifas y actividades admitidas cambian por año: confirmar en la DIAN. Dónde confirmar: dian.gov.co y normograma.dian.gov.co.$k$,
$k$DIAN (normograma) / Función Pública$k$,$k$https://normograma.dian.gov.co/dian/compilacion/docs/decreto_4910_2011.htm$k$,
$k$Material informativo de entidades oficiales colombianas y textos legales, con apoyo de una fuente profesional (Accounter); no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','finanzas','PY',$k$ley_mipymes_4457_cedula_beneficios$k$,$k$Paraguay: Ley MIPYMES (Ley 4457/12 modificada por Ley 7444/2024) y Cédula MIPYMES$k$,
$k$Orientación general (confirmar con contador). La Ley 4457/2012 regula a las micro, pequeñas y medianas empresas y fue modificada por la Ley 7444/2024, promulgada en enero de 2025. El MIC emite la Cédula MIPYMES (Registro Nacional de MIPYMES), que da acceso a beneficios como facilidades en el trámite de constitución, preferencias en compras públicas (subastas a la baja electrónica de la DNCP) y acceso a financiamiento. Según el resumen de LEAP/UNEP, la reforma introduce exoneraciones tributarias, descuentos en patentes comerciales y acceso preferente a contrataciones públicas. Prensa indicó en abril de 2025 que faltaba la reglamentación para acceder a los beneficios: confirmar su estado actual. No son MIPYMES las empresas de intermediación financiera, seguros, inmobiliarias y profesiones liberales (art. 6). Dónde confirmar: mic.gov.py, mipymes.gov.py y dnit.gov.py.$k$,
$k$MIC / BACN$k$,$k$https://mic.gov.py/wp-content/uploads/2024/12/FICHA-MIPYMES_ESPANOL.pdf$k$,
$k$Material informativo de entidades oficiales paraguayas, con apoyo de prensa y de LEAP/UNEP; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','CL',$k$regimen_pro_pyme_14d3_transparencia_14d8$k$,$k$Chile: Régimen Pro Pyme (14 D N°3) y Pro Pyme Transparente (14 D N°8)$k$,
$k$Orientación general (confirmar con contador). Desde 2020 la Ley de la Renta contempla regímenes especiales para micro, pequeñas y medianas empresas: Pro Pyme General (art. 14 D N°3) y Pro Pyme Transparente (art. 14 D N°8). En el Pro Pyme, el SII indica entre sus características la liberación de corrección monetaria y la depreciación instantánea e íntegra de los activos físicos en el ejercicio de adquisición. En el General la empresa paga el impuesto de primera categoría; en el Transparente la empresa queda liberada de ese impuesto y tributan directamente los dueños con impuestos finales (fuente profesional). Los requisitos de ingreso (por ejemplo, topes en UF) provienen de presentaciones profesionales: confirmar en SII. La Ley 21.210 amplió también la depreciación instantánea del 100% para ciertos bienes. Dónde confirmar: sii.cl (Operación Renta, regímenes).$k$,
$k$SII$k$,$k$https://www.sii.cl/preguntas_frecuentes/ddjj/001_135_8805.htm$k$,
$k$Material informativo del SII, con apoyo de fuentes profesionales (Nubox, CCS); no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','finanzas','AR',$k$monotributo_certificado_mipyme_beneficios$k$,$k$Argentina: Monotributo, Certificado MiPyME y beneficios$k$,
$k$Orientación general (confirmar con contador). El Monotributo es un régimen para pequeños contribuyentes que unifica el pago de IVA y Ganancias con los aportes jubilatorios y la obra social (ARCA); quien no cumple sus requisitos va al Régimen General. El Certificado MiPyME acredita la condición de micro, pequeña o mediana empresa y permite acceder a financiamiento, beneficios impositivos y programas de asistencia; ARCA informó beneficios como pagar el IVA a 90 días y compensar Ganancias con el impuesto al cheque (novedad de mayo de 2024: verificar vigencia). Se solicita con CUIT, Clave Fiscal nivel 2 o superior, alta en Monotributo o Régimen General y adhesión a Trámites a Distancia (TAD), desde el servicio PYMES Solicitud de Categorización y/o Beneficios. El Monotributo Promovido exime del impuesto integrado mientras se permanece en el régimen. Categorías y topes se actualizan: confirmar en ARCA.$k$,
$k$ARCA / argentina.gob.ar$k$,$k$https://www.argentina.gob.ar/node/216991$k$,
$k$Material informativo de portales oficiales argentinos; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','BR',$k$simples_nacional_me_epp_das$k$,$k$Brasil: Simples Nacional para ME y EPP$k$,
$k$Orientación general (confirmar con contador). El Simples Nacional se regula por la Lei Complementar 123/2006 y unifica varios tributos en una guía mensual (DAS), que según una fuente profesional reúne hasta ocho tributos; se declara por el PGDAS-D. Límites de referencia 2026 según fuentes profesionales (no verificados en la Receita): ME hasta R$ 360.000 y EPP hasta R$ 4,8 millones de receita bruta anual, con sublimite estadual de R$ 3,6 millones para ICMS/ISS; MEI hasta R$ 81.000. Hay cinco anexos con alícuotas por actividad. Para optar no se deben tener débitos en abierto con la Unión, estados o municipios, y existen actividades vedadas. Superar el límite genera desenquadramento con plazos distintos según el exceso. La reforma tributaria en curso puede cambiar reglas: confirmar. Dónde confirmar: Portal do Simples Nacional (Receita Federal) y su manual de preguntas frecuentes.$k$,
$k$Receita Federal (Simples Nacional)$k$,$k$https://www8.receita.fazenda.gov.br/SimplesNacional/Arquivos/manual/perguntaosn.pdf$k$,
$k$Material informativo de la Receita Federal, con apoyo de fuentes profesionales (Agilize, Contabilizei) para cifras; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','MX',$k$resico_personas_morales_plan_mexico$k$,$k$México: Régimen Simplificado de Confianza (RESICO) y estímulos del Decreto Plan México$k$,
$k$Orientación general (confirmar con contador). El RESICO existe para personas físicas y para personas morales. Para personas morales, fuentes de prensa y académicas lo describen para sociedades constituidas únicamente por personas físicas, residentes en México, con ingresos totales de hasta 35 millones de pesos en el ejercicio; para personas físicas el tope citado es de 3.5 millones. Si se supera el límite, el SAT puede reclasificar al régimen que corresponda. El SAT publicó una guía para aplicar en la declaración anual de personas morales los beneficios del Decreto Plan México, para quienes tributan en el Régimen General de Ley o en el RESICO, con RFC, Buzón Tributario habilitado y opinión de cumplimiento positiva. Requisitos, topes y estímulos cambian con la miscelánea fiscal: confirmar el año vigente. Dónde confirmar: sat.gob.mx (Regímenes fiscales, Plan México).$k$,
$k$SAT$k$,$k$https://www.sat.gob.mx/minisitio/DeclaracionAnual/Empresas/documentos/GuiaLlenado_PlanMX2025.pdf$k$,
$k$Material informativo del SAT, con apoyo de prensa y fuentes académicas para los topes; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','EC',$k$rimpe_emprendedores_negocios_populares$k$,$k$Ecuador: RIMPE (emprendedores y negocios populares)$k$,
$k$Orientación general (confirmar con contador). El RIMPE (Régimen Simplificado para Emprendedores y Negocios Populares) rige desde 2022 y reemplazó al RISE, bajo normas del SRI. Dos grupos según ingresos brutos anuales: negocios populares (hasta USD 20.000) y emprendedores (hasta USD 300.000), según fuentes periodísticas y profesionales. Los negocios populares pueden usar notas de venta con la leyenda correspondiente y, según esas fuentes, no están sujetos a retención de IVA ni de renta; los emprendedores deben emitir facturas electrónicas y declarar periódicamente. No pueden acogerse, entre otros, quienes presten servicios profesionales con título de tercer nivel y los trabajadores en relación de dependencia. Quien cambia de condición debe actualizar su RUC. Topes, cuotas y plazos de permanencia cambian por reforma: confirmar en el SRI. Dónde confirmar: sri.gob.ec y gob.ec.$k$,
$k$SRI (resolución NAC-DGERCGC21-00000060) / gob.ec$k$,$k$https://www.ey.com/content/dam/ey-unified-site/ey-com/es-ec/technical/tax/documents/ey-ene12-taxalert-resolucion-no60-normas-aplicacion-rimpe.pdf$k$,
$k$Material informativo basado en la normativa del SRI, con apoyo de firmas profesionales (EY, Andersen) y prensa; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','UY',$k$monotributo_literal_e_iva_minimo$k$,$k$Uruguay: Monotributo, Monotributo Social MIDES y Pequeña Empresa (Literal E, IVA mínimo)$k$,
$k$Orientación general (confirmar con contador). La DGI publica una guía comparativa de Monotributo y Pequeña Empresa (régimen de IVA mínimo, Literal E del art. 52) según actividad, naturaleza jurídica, ingresos, activos, personal y pagos. Para IVA mínimo, una fuente profesional cita un tope de 305.000 UI y la obligación de comunicar a DGI si se supera o si se opta por IRAE e IVA por régimen general; el sitio de la DGI menciona 305000 UI para sociedades de hecho en Monotributo. El Monotributo Social MIDES admite asociativos de hasta cinco integrantes y se inscribe desde MIDES con el formulario 0356 y trámite final en DGI y BPS. Las unipersonales de Pequeña Empresa y Monotributo no están obligadas a ciertos formularios patrimoniales. Topes en UI y pesos se actualizan: confirmar. Dónde confirmar: gub.uy/direccion-general-impositiva y bps.gub.uy.$k$,
$k$DGI / BPS / MIDES$k$,$k$https://www.gub.uy/direccion-general-impositiva/comunicacion/publicaciones/comparacion-pequena-empresa-monotributo$k$,
$k$Material informativo de portales oficiales uruguayos, con apoyo de una fuente profesional (Tributo Simple) para el tope; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft');